// n8n Code node: "extract_vendor"   (mode: Run Once for Each Item)
// Input : output of the PRESIDIO HTTP node -> { anonymized_text, mapping }
// Output: { company_name, company_placeholder, content_sha256 }
//
// Picks the *main* vendor among the COMPANY_* entities found by Presidio.
// Heuristic (fixes the old "COMPANY_001 is always the vendor" bug):
//   1. drop known certification bodies / auditors (SGS, AENOR, BSI, ...)
//   2. prefer names with a legal suffix (S.L., S.A., S.L.U., GmbH, Ltd, Inc...)
//   3. rank by number of mentions in the anonymized text, then by first position

const LEGAL_SUFFIX = /\b(S\.?\s?L\.?\s?U?\.?|S\.?\s?A\.?\s?U?\.?|S\.?\s?C\.?\s?A\.?|GmbH|Ltd\.?|Limited|Inc\.?|LLC|B\.?V\.?|SAS|SpA|AG)\s*$/i;

const CERTIFIERS = [
  'sgs', 'aenor', 'bureau veritas', 'bsi', 'tüv', 'tuv', 'dnv', 'lrqa', 'applus',
  'intertek', 'eqa', 'lloyd', 'kpmg', 'deloitte', 'pwc', 'ernst & young', 'ey ',
  'schellman', 'a-lign', 'coalfire', 'enac', 'ccn',
];

function isCertifier(name) {
  const n = ` ${name.toLowerCase()} `;
  return CERTIFIERS.some((c) => n.includes(` ${c.trim()}`));
}

function pickVendor(anonymizedText, mapping) {
  const text = anonymizedText || '';
  const candidates = Object.entries(mapping || {})
    .filter(([key]) => key.startsWith('COMPANY_'))
    .map(([key, value]) => {
      const tag = `<${key}>`;
      const mentions = text.split(tag).length - 1;
      const firstPos = text.indexOf(tag);
      return {
        key,
        value: String(value).trim(),
        mentions,
        firstPos: firstPos === -1 ? Number.MAX_SAFE_INTEGER : firstPos,
        legal: LEGAL_SUFFIX.test(String(value).trim()),
        certifier: isCertifier(String(value)),
      };
    })
    .filter((c) => !c.certifier);

  if (candidates.length === 0) return null;

  candidates.sort(
    (a, b) =>
      Number(b.legal) - Number(a.legal) ||
      b.mentions - a.mentions ||
      a.firstPos - b.firstPos
  );
  return candidates[0];
}

function sha256(text) {
  // NODE_FUNCTION_ALLOW_BUILTIN=crypto must be set for n8n (see docker-compose.yml)
  return require('crypto').createHash('sha256').update(text || '', 'utf8').digest('hex');
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { pickVendor, isCertifier, sha256 };
}

// ---- n8n entry point -------------------------------------------------------
if (typeof $input !== 'undefined') {
  const { anonymized_text, mapping } = $input.item.json;
  const vendor = pickVendor(anonymized_text, mapping);
  return {
    json: {
      company_name: vendor ? vendor.value : 'PROVEEDOR_NO_IDENTIFICADO',
      company_placeholder: vendor ? vendor.key : null,
      content_sha256: sha256(anonymized_text),
    },
  };
}

// n8n Code node: "build_prompt"   (mode: Run Once for Each Item)
// Previous node: "Lee Prompt" (Read/Write Files from Disk -> Extract from File as text)
//   reading /home/node/.n8n-files/maestro/prompt_tprm.txt
// Output: OpenRouter chat-completions body -> { model, temperature, messages }
//
// The master prompt contains the marker [EL DOCUMENTO SE AÑADIRÁ AQUÍ].
// Everything except the document goes to the `system` role; the anonymized
// document goes alone to the `user` role. Only anonymized text ever leaves n8n.

const MARKER = '[EL DOCUMENTO SE AÑADIRÁ AQUÍ]';
const DEFAULT_MODEL = 'meta-llama/llama-3.3-70b-instruct:free';

function buildMessages(promptTemplate, anonymizedText) {
  if (!promptTemplate || !promptTemplate.includes(MARKER)) {
    throw new Error(`Prompt template is missing the marker ${MARKER}`);
  }
  const [before, after] = promptTemplate.split(MARKER);
  const system = `${before.replace(/DOCUMENTO A ANALIZAR:\s*$/i, '').trim()}\n\n${after.trim()}`;
  const user = `DOCUMENTO A ANALIZAR (anonimizado):\n\n${anonymizedText}`;
  return [
    { role: 'system', content: system },
    { role: 'user', content: user },
  ];
}

function buildBody(promptTemplate, anonymizedText, model) {
  return {
    model: model || DEFAULT_MODEL,
    temperature: 0,
    messages: buildMessages(promptTemplate, anonymizedText),
  };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { buildMessages, buildBody, MARKER };
}

// ---- n8n entry point -------------------------------------------------------
if (typeof $input !== 'undefined') {
  const prompt = $input.item.json.data;                       // text from "Lee Prompt"
  const anonymized = $('PRESIDIO').item.json.anonymized_text;
  const model = (typeof $env !== 'undefined' && $env.OPENROUTER_MODEL) || DEFAULT_MODEL;
  return { json: buildBody(prompt, anonymized, model) };
}

// n8n Code node: "clean_llm_json"   (mode: Run Once for Each Item)
// Input : OpenRouter response -> choices[0].message.content
// Output: parsed TPRM assessment object
//
// LLMs often wrap JSON in ```json fences or add a sentence before/after.
// This strips that noise and fails loudly (with a preview) if it is not JSON.

function extractJson(raw) {
  if (raw && typeof raw === 'object') return raw;
  let text = String(raw || '').trim();
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1 || end < start) {
    throw new Error(`LLM response has no JSON object: ${text.slice(0, 200)}`);
  }
  const candidate = text.slice(start, end + 1);
  try {
    return JSON.parse(candidate);
  } catch (err) {
    throw new Error(`Invalid JSON from LLM (${err.message}): ${candidate.slice(0, 200)}`);
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { extractJson };
}

// ---- n8n entry point -------------------------------------------------------
if (typeof $input !== 'undefined') {
  const content = $input.item.json.choices?.[0]?.message?.content;
  return { json: extractJson(content) };
}

// n8n Code node: "deanonymize"   (mode: Run Once for Each Item)
// Input : assessment JSON with placeholders (<COMPANY_001>, <EMAIL_001>, ...)
// Output: same JSON with the real values restored
//
// The mapping is taken from the PRESIDIO node of the *same execution*
// (in memory). It is never sent to the LLM.

const PLACEHOLDER = /<([A-Z_]+_\d{3})>/g;

function restore(value, mapping) {
  if (typeof value === 'string') {
    return value.replace(PLACEHOLDER, (match, key) =>
      Object.prototype.hasOwnProperty.call(mapping, key) ? mapping[key] : match
    );
  }
  if (Array.isArray(value)) return value.map((v) => restore(v, mapping));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, restore(v, mapping)]));
  }
  return value;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { restore };
}

// ---- n8n entry point -------------------------------------------------------
if (typeof $input !== 'undefined') {
  const mapping = $('PRESIDIO').item.json.mapping || {};
  return { json: restore($input.item.json, mapping) };
}

// n8n Code node: "compute_score"   (mode: Run Once for Each Item)
// Input : de-anonymized assessment JSON from the LLM
// Output: { ...assessment, scoring: {..., score_total, resultado, secciones}, db: {...} }
//
// The LLM is asked for per-control scores (1-5). Its own score_total/resultado
// were unreliable (often null or inconsistent), so the final score is computed
// here, deterministically, following the rules of prompts/prompt_tprm.txt:
//   - section score  = mean of non-null controls (null if >50% of controls are null)
//   - total (0-100)  = sum(section_mean * weight) * 20
//   - >=80 Aprobado | 60-79 Aprobado con condiciones | <60 Rechazado
//   - any null section -> "Evaluación incompleta"
//   - any gap with bloquea_aprobacion=true caps the result at "Rechazado"

const SECTIONS = {
  s1: { name: 'Seguridad de la información', weight: 0.30 },
  s2: { name: 'Gestión de accesos e identidades (IAM)', weight: 0.25 },
  s3: { name: 'Continuidad de negocio', weight: 0.15 },
  s4: { name: 'Protección de datos', weight: 0.20 },
  s5: { name: 'Seguridad en la nube', weight: 0.05 },
  s6: { name: 'Subcontratistas', weight: 0.05 },
};

// Fields inside `scoring` that are data, not 1-5 scores
const NON_SCORE_FIELDS = new Set([
  's3_rto_horas', 's3_rpo_horas', 's4_paises_transferencia', 'score_total', 'resultado',
]);

function toScore(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) && n >= 1 && n <= 5 ? n : null;
}

function computeScore(scoring = {}, gaps = []) {
  const secciones = {};
  let total = 0;
  let incomplete = false;

  for (const [prefix, meta] of Object.entries(SECTIONS)) {
    const keys = Object.keys(scoring).filter(
      (k) => k.startsWith(`${prefix}_`) && !NON_SCORE_FIELDS.has(k)
    );
    const values = keys.map((k) => toScore(scoring[k])).filter((v) => v !== null);
    const nullRatio = keys.length ? 1 - values.length / keys.length : 1;
    const mean = values.length && nullRatio <= 0.5
      ? values.reduce((a, b) => a + b, 0) / values.length
      : null;

    secciones[prefix] = {
      nombre: meta.name,
      peso: meta.weight,
      controles: keys.length,
      evaluados: values.length,
      media: mean === null ? null : Math.round(mean * 100) / 100,
    };
    if (mean === null) incomplete = true;
    else total += mean * meta.weight;
  }

  const blocking = (Array.isArray(gaps) ? gaps : []).filter(
    (g) => g && (g.bloquea_aprobacion === true || g.bloquea_aprobacion === 'true')
  );

  let score_total = incomplete ? null : Math.round(total * 20);
  let resultado;
  if (incomplete) resultado = 'Evaluación incompleta';
  else if (score_total >= 80) resultado = 'Aprobado';
  else if (score_total >= 60) resultado = 'Aprobado con condiciones';
  else resultado = 'Rechazado';

  if (blocking.length && resultado !== 'Evaluación incompleta') resultado = 'Rechazado';

  return { score_total, resultado, secciones, gaps_bloqueantes: blocking.length };
}

function firstCertExpiry(cert = {}) {
  return cert.iso_27001_hasta || cert.ens_hasta || cert.soc2_hasta || null;
}

function toDbParams(a) {
  const v = a.vendor || {};
  const s = a.scoring || {};
  const json = (x) => (x === undefined || x === null ? null : JSON.stringify(x));
  return {
    company_name: v.nombre,
    tipo_servicio: v.tipo_servicio ?? null,
    tier: v.tier ?? null,
    dpo_nombre: v.dpo_nombre ?? null,
    dpo_email: v.dpo_email ?? null,
    dpo_tipo: v.dpo_tipo ?? null,
    country: v.pais_servicio ?? null,
    localizacion_datos: v.localizacion_datos ?? null,
    subcontratistas: json(v.subcontratistas),
    certificaciones: json(a.certificaciones),
    cert_expiry: firstCertExpiry(a.certificaciones),
    scoring: json(s),
    gaps: json(a.gaps),
    campos_pendientes: json(a.campos_pendientes),
    overall_score: s.score_total ?? null,
    current_risk: s.resultado ?? null,
    summary: a.resumen_ejecutivo ?? null,
  };
}

function enrich(assessment, fallbackVendorName) {
  const a = JSON.parse(JSON.stringify(assessment || {}));
  a.vendor = a.vendor || {};
  if (!a.vendor.nombre && fallbackVendorName) a.vendor.nombre = fallbackVendorName;
  const result = computeScore(a.scoring || {}, a.gaps || []);
  a.scoring = {
    ...(a.scoring || {}),
    score_llm: a.scoring?.score_total ?? null,   // keep what the LLM said, for audit
    score_total: result.score_total,
    resultado: result.resultado,
    secciones: result.secciones,
  };
  a.db = toDbParams(a);
  return a;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { computeScore, enrich, toDbParams, SECTIONS };
}

// ---- n8n entry point -------------------------------------------------------
if (typeof $input !== 'undefined') {
  let fallback = null;
  try { fallback = $('extract_vendor').item.json.company_name; } catch (e) { /* optional */ }
  return { json: enrich($input.item.json, fallback) };
}
